def compiler_num_devices_kwarg() -> str:
    # 공용 헬퍼 한 곳에서 rebel.__version__ 비교
    if compiler_version_at_least("0.9.2"):
        return "num_devices"
    return "tensor_parallel_size"

def compiler_num_devices_kwarg() -> str:
    params = inspect.signature(rebel.compile).parameters
    if "num_devices" in params:
        return "num_devices"
    return "tensor_parallel_size"  # -> 구버전은 이전 이름으로 그대로 컴파일

def compiler_num_devices_kwarg() -> str:
    params = inspect.signature(rebel.compile).parameters
    if "num_devices" in params:
        return "num_devices"
    raise RuntimeError("rebel-compiler is too old; please upgrade it.")

